from pypdf import PdfReader

reader = PdfReader("/root/sc100-blank.pdf")
fields = reader.get_fields()

target_fields = [
    "SC-100[0].Page3[0].List4[0].Item4[0].Checkbox50[0]",
    "SC-100[0].Page3[0].List4[0].Item4[0].Checkbox50[1]",
    "SC-100[0].Page3[0].List5[0].Lia[0].Checkbox5cb[0]",
]

if fields:
    for field_name in target_fields:
        if field_name in fields:
            print(f"Field: {field_name}")
            print(f"  Type: {fields[field_name].get('/FT')}")
            print(f"  Kids: {fields[field_name].get('/Kids')}")
            # Try to find options or appearance states
            if '/Opt' in fields[field_name]:
                print(f"  Opt: {fields[field_name]['/Opt']}")
            if '/AP' in fields[field_name]:
                 print(f"  AP: {fields[field_name]['/AP'].keys() if hasattr(fields[field_name]['/AP'], 'keys') else 'No keys'}")
            # Sometimes options are in the widget annotation directly

else:
    print("No fields found.")

